{
  "findings": [
    {
      "check_id": "CKV_AZURE_229",
      "title": "Ensure the Azure SQL Database Namespace is zone redundant",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "The Azure SQL Database is not zone redundant, which may impact availability during zone outages."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"trading_database\" {\n  name           = \"trading-database\"\n  server_id      = azurerm_mssql_server.trading_sql_server.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 100\n  sku_name       = \"S2\"\n  zone_redundant = true\n}",
  "fix_summary": "Enabled zone redundancy for the Azure SQL Database to improve availability."
}
